css:
.fundprog-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #20272f;
    background: linear-gradient(170deg, #f7f3ea 0%, #f1ece1 55%, #ece4d6 100%);
    border-radius: 18px;
}

.fundprog-container * {
    box-sizing: border-box;
}

.fundprog-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #14233f 0%, #1f3a63 55%, #2b4f80 100%);
    color: #f4f1e8;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(20, 35, 63, 0.32);
    border-bottom: 4px solid #c9a23f;
}

.fundprog-header h1 {
    margin: 12px 0 12px;
    font-size: 2.45rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.fundprog-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f0d588;
    background: rgba(201, 162, 63, 0.16);
    border: 1px solid rgba(201, 162, 63, 0.45);
    padding: 5px 14px;
    border-radius: 999px;
}

.fundprog-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.6;
    color: #dfe3ee;
}

.fundprog-lines {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.fundprog-line {
    flex: 1;
    background: #fffdf8;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(32, 39, 47, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.fundprog-line-open { border-left: 5px solid #2b4f80; }
.fundprog-line-custom { border-left: 5px solid #c9a23f; }

.fundprog-line-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #14233f;
}

.fundprog-line-open .fundprog-line-name { color: #2b4f80; }
.fundprog-line-custom .fundprog-line-name { color: #9c7716; }

.fundprog-line-meta {
    font-size: 0.82rem;
    color: #5e6670;
    line-height: 1.4;
}

.fundprog-line-plus {
    align-self: center;
    font-size: 1.6rem;
    font-weight: 800;
    color: #1f3a63;
}

.fundprog-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #46505d;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.fundprog-period-counter #currentDay,
.fundprog-period-counter #maxPeriods {
    font-weight: 800;
    color: #2b4f80;
}

.fundprog-round-name {
    background: rgba(43, 79, 128, 0.13);
    color: #1f3a63;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.fundprog-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9c7716;
    background: rgba(201, 162, 63, 0.16);
    border: 1px solid rgba(201, 162, 63, 0.34);
    padding: 4px 12px;
    border-radius: 999px;
}

.fundprog-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.fundprog-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(32, 39, 47, 0.08);
    border-top: 4px solid #1f3a63;
}

.fundprog-card-margin { border-top-color: #2b4f80; }
.fundprog-card-fill { border-top-color: #2f8f7a; }
.fundprog-card-contrib { border-top-color: #c9a23f; }
.fundprog-card-health { border-top-color: #7d5fc0; }

.fundprog-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b727c;
}

.fundprog-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14233f;
    font-variant-numeric: tabular-nums;
}

.fundprog-card-margin .fundprog-value { color: #2b4f80; }
.fundprog-card-fill .fundprog-value { color: #2f8f7a; }
.fundprog-card-contrib .fundprog-value { color: #9c7716; }
.fundprog-card-health .fundprog-value { color: #7d5fc0; }

.fundprog-sublabel {
    font-size: 0.76rem;
    color: #79808b;
    line-height: 1.35;
}

/* Margin card states relative to the 35% floor. */
.fundprog-card-margin.fundprog-margin-pass { border-top-color: #2f8f7a; }
.fundprog-card-margin.fundprog-margin-pass .fundprog-value { color: #2f8f7a; }
.fundprog-card-margin.fundprog-margin-fail { border-top-color: #cc4b3c; }
.fundprog-card-margin.fundprog-margin-fail .fundprog-value { color: #cc4b3c; }

.fundprog-floor-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffdf8;
    border: 1px solid #e4ddcd;
    color: #46505d;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.fundprog-floor-bar #floorDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #cc4b3c;
    font-weight: 800;
}

.fundprog-floor-bar.fundprog-floor-ok #floorDisplay { color: #2f8f7a; }
.fundprog-floor-bar.fundprog-floor-near #floorDisplay { color: #9c7716; }

.fundprog-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #c9a23f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(32, 39, 47, 0.07);
}

.fundprog-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.fundprog-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14233f;
    margin-bottom: 6px;
}

.fundprog-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #3a434f;
}

.fundprog-briefing-text strong { color: #1f3a63; }
.fundprog-briefing-text em { color: #9c7716; font-style: italic; }

.fundprog-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(32, 39, 47, 0.07);
}

.fundprog-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14233f;
    border-bottom: 2px solid #ece4d3;
    padding-bottom: 8px;
}

.fundprog-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b3540;
    margin: 14px 0 6px;
}

.fundprog-container select,
.fundprog-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cfc6b2;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #20272f;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.fundprog-container select:focus,
.fundprog-container input[type="number"]:focus {
    outline: none;
    border-color: #2b4f80;
    box-shadow: 0 0 0 3px rgba(43, 79, 128, 0.16);
}

.fundprog-container select option {
    background-color: #ffffff;
    color: #20272f;
}

.fundprog-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2b4f80;
}

.fundprog-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #46505d;
    margin-top: 4px;
}

.fundprog-range-readout span:nth-child(2) {
    color: #2b4f80;
    font-weight: 800;
}

.fundprog-hint {
    font-size: 0.8rem;
    color: #79808b;
    margin-top: 6px;
    line-height: 1.42;
    font-style: italic;
}

.fundprog-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.fundprog-container .btn-primary {
    background: linear-gradient(135deg, #1f3a63 0%, #2b4f80 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(31, 58, 99, 0.32);
}

.fundprog-container .btn-primary:hover {
    filter: brightness(1.08);
}

.fundprog-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #cfc6b2;
    color: #5e6670;
    background: transparent;
}

.fundprog-coach {
    background: linear-gradient(160deg, #14233f 0%, #1c3357 100%);
    color: #e6e9f1;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(20, 35, 63, 0.26);
    border-left: 5px solid #c9a23f;
}

.fundprog-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0d588;
    margin-bottom: 8px;
}

.fundprog-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.fundprog-coach-body strong { color: #8fd4c4; }
.fundprog-coach-body em { color: #f0d588; font-style: italic; }

.fundprog-history,
.fundprog-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(32, 39, 47, 0.07);
}

.fundprog-history h3,
.fundprog-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14233f;
}

.fundprog-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a434f;
}

.fundprog-container table#usfHistoryTable th {
    background: #f2ecdd;
    color: #1f3a63;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd3bc;
}

.fundprog-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efeadd;
    color: #3a434f;
}

.fundprog-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf6ec;
}

.fundprog-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .fundprog-container {
        padding: 14px;
    }
    .fundprog-header h1 {
        font-size: 1.7rem;
    }
    .fundprog-lines {
        flex-direction: column;
    }
    .fundprog-line-plus {
        transform: rotate(90deg);
    }
    .fundprog-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .fundprog-value {
        font-size: 2rem;
    }
    .fundprog-clock {
        margin-left: 0;
    }
    .fundprog-period-counter {
        font-size: 0.88rem;
    }
    .fundprog-floor-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .fundprog-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-funding debrief scorecard (append-only, namespaced) ===== */
.fp-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.fp-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #7a8398; margin-bottom: 6px; }
.fp-cm-verdict { font-size: 22px; font-weight: 700; color: #eceff6; margin-bottom: 8px; }
.fp-cm-score { font-size: 16px; color: #eceff6; margin-bottom: 16px; }
.fp-cm-score strong { color: #4f9bd9; }
.fp-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #7a8398; margin-bottom: 8px; }
.fp-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.fp-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.fp-cm-target.fp-cm-met { background: rgba(79,155,217,0.16); color: #8fc3ea; border-color: rgba(79,155,217,0.4); }
.fp-cm-target.fp-cm-missed { background: rgba(255,110,110,0.14); color: #ff9d9d; border-color: rgba(255,110,110,0.36); }
.fp-cm-tick { font-weight: 700; }
.fp-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.fp-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,135,175,0.12); border-radius: 8px; min-width: 92px; }
.fp-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #7a8398; }
.fp-cm-metric strong { font-size: 16px; color: #eceff6; }
.fp-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.fp-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(79,155,217,0.10); border-left: 3px solid #4f9bd9; border-radius: 4px; color: #dde5f1; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .fp-cm-metric { min-width: 70px; } .fp-cm-verdict { font-size: 19px; } }

