(function() {
    'use strict';

    class FundProgramAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Fund the Program`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (EAGP, Peru / PEN). ----
            this.REVENUE = 24.0;           // S/ 24,000,000 annual revenue (in S/ millions)
            this.START_MARGIN = 31;        // prior-year blended contribution margin (%)
            this.FLOOR = 35;               // board-set contribution-margin floor (%)
            this.START_FILL = 62;          // average classroom fill rate (%)
            this.FRONTIER = 75;            // efficient-frontier fill rate for exec-ed (%)
            this.START_HEALTH = 70;        // strategic-health index 0–100 (brand/pipeline/talent/quality)
            this.LEASE = 1.4;              // adjacent floor lease option (S/ M / year, opex)
            this.CAPEX = 5.2;              // adjacent floor own option (S/ M, capex)
            this.CAP_UPLIFT = 33;          // +33% capacity from the new floor (%)
            this.MINING_CONTRIB = 0.47;    // S/ 470K of contribution at risk (S/ M)

            // Concept "best answers" for summary verdicts.
            this.TRUE_CLASSIFY = `segment`;
            this.TRUE_PRICING = `segmented`;
            this.TRUE_MIX = `balanced`;
            this.TRUE_INVEST = `lease`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    margin: this.START_MARGIN,       // blended contribution margin (%)
                    fill: this.START_FILL,           // capacity fill rate (%)
                    contribution: Math.round(this.REVENUE * this.START_MARGIN) / 100, // S/ M
                    health: this.START_HEALTH,       // strategic-health index 0–100

                    flagshipKilled: false,           // killed the PAD on contribution alone
                    uniformHike: false,              // across-the-board price rise
                    concededClient: false,           // gave the mining cut for nothing
                    overInvested: false,             // sank capex on an optimistic ramp
                    qualityCut: false,               // slashed variable spend / NPS hit
                    capacityBreached: false,         // grew custom past faculty ceiling

                    benchSpent: 0,                   // S/ K invested in adjunct bench / QA
                    investChoice: ``,                // final capacity decision label code
                    roi: 0,                          // computed ROI on the capacity bet (%)
                    payback: 0,                      // computed payback period (years)
                    breakeven: 0,                    // break-even fill rate for new space (%)

                    marginHistory: [this.START_MARGIN],
                    fillHistory: [this.START_FILL],
                    contribHistory: [Math.round(this.REVENUE * this.START_MARGIN) / 100],
                    healthHistory: [this.START_HEALTH],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    classify: `single`,
                    pad: `kill`,
                    overhead: `literal`,
                    focus: 40,
                    pricing: `uniform`,
                    discount: `deep`,
                    variable: `slash`,
                    premium: 0,
                    mix: `custompush`,
                    faculty: `overbook`,
                    client: `concede`,
                    bench: 0,
                    invest: `own`,
                    scenario: `optimistic`,
                    breakeven: `skip`,
                    confidence: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const cl = document.getElementById(`classifyInput`);
                const pa = document.getElementById(`padInput`);
                const ov = document.getElementById(`overheadInput`);
                const fo = document.getElementById(`focusInput`);
                if (cl) decisions.classify = cl.value;
                if (pa) decisions.pad = pa.value;
                if (ov) decisions.overhead = ov.value;
                if (fo) decisions.focus = parseInt(fo.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const pr = document.getElementById(`pricingInput`);
                const di = document.getElementById(`discountInput`);
                const va = document.getElementById(`variableInput`);
                const pm = document.getElementById(`premiumInput`);
                if (pr) decisions.pricing = pr.value;
                if (di) decisions.discount = di.value;
                if (va) decisions.variable = va.value;
                if (pm) decisions.premium = parseInt(pm.value, 10);
                if (!Number.isFinite(decisions.premium) || decisions.premium < -10 || decisions.premium > 20) {
                    warn(`warn_premium_range`); return false;
                }
            } else if (round === 3) {
                const mi = document.getElementById(`mixInput`);
                const fa = document.getElementById(`facultyInput`);
                const cli = document.getElementById(`clientInput`);
                const be = document.getElementById(`benchInput`);
                if (mi) decisions.mix = mi.value;
                if (fa) decisions.faculty = fa.value;
                if (cli) decisions.client = cli.value;
                if (be) decisions.bench = parseFloat(be.value);
                if (!Number.isFinite(decisions.bench) || decisions.bench < 0) {
                    warn(`warn_bench_value`); return false;
                }
            } else if (round === 4) {
                const inv = document.getElementById(`investInput`);
                const sc = document.getElementById(`scenarioInput`);
                const br = document.getElementById(`breakevenInput`);
                const co = document.getElementById(`confidenceInput`);
                if (inv) decisions.invest = inv.value;
                if (sc) decisions.scenario = sc.value;
                if (br) decisions.breakeven = br.value;
                if (co) decisions.confidence = parseInt(co.value, 10);
                if (!Number.isFinite(decisions.confidence) || decisions.confidence < 0 || decisions.confidence > 100) {
                    warn(`warn_confidence_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let marginDelta = 0, fillDelta = 0, healthDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Read the portfolio — diagnosis quality sets up everything else.
                switch (d.classify) {
                    case `segment`: marginDelta += 1.0; healthDelta += 4; coachKey = `coach_r1_segment`; break;
                    case `cutall`: marginDelta += 0.4; fillDelta -= 3; healthDelta -= 6; coachKey = `coach_r1_cutall`; break;
                    case `single`: healthDelta -= 3; coachKey = `coach_r1_single`; break;
                }

                switch (d.pad) {
                    case `strategic`: healthDelta += 8; marginDelta -= 0.2; coachKey = `coach_r1_padstrategic`; break;
                    case `kill`: ds.flagshipKilled = true; marginDelta += 1.2; healthDelta -= 18; coachKey = `coach_r1_padkill`; break;
                    case `ignore`: healthDelta -= 2; coachKey = `coach_r1_padignore`; break;
                }

                switch (d.overhead) {
                    case `contribution`: marginDelta += 0.6; healthDelta += 3; break;
                    case `literal`: healthDelta -= 2; coachKey = `coach_r1_overhead`; break;
                    case `ignore`: marginDelta -= 0.6; healthDelta -= 4; coachKey = `coach_r1_revenue`; break;
                }

                // Analytical rigor on the contribution map.
                if (d.focus >= 60) { healthDelta += 3; marginDelta += 0.3; }
                else if (d.focus <= 25) { healthDelta -= 3; coachKey = `coach_r1_norigor`; }

                summaryKey = (d.classify === `segment` && d.pad === `strategic` && d.overhead === `contribution`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Reprice the open-enrollment portfolio (elasticity + segmentation).
                if (d.pricing === `uniform`) {
                    // Across-the-board hike: elastic mid-tier sheds enrollment, fill drops.
                    ds.uniformHike = true;
                    marginDelta += 0.8;        // looks like margin on paper...
                    fillDelta -= 7;            // ...but fill falls 62 -> ~55
                    healthDelta -= 5;
                    coachKey = `coach_r2_uniform`;
                } else if (d.pricing === `discount`) {
                    // Chase volume by discounting: fill up a touch, margin destroyed, brand erodes.
                    fillDelta += 4;
                    marginDelta -= 2.0;
                    healthDelta -= 6;
                    coachKey = `coach_r2_discount`;
                } else { // segmented
                    marginDelta += 2.6;
                    fillDelta += 3;
                    healthDelta += 4;
                    coachKey = `coach_r2_segmented`;
                    // Pricing power: a modest premium on strong programs is rewarded; an
                    // aggressive one prices out even the inelastic segment.
                    const p = d.premium;
                    if (p >= 1 && p <= 8) { marginDelta += 1.0; }
                    else if (p > 12) { fillDelta -= 5; marginDelta -= 0.6; coachKey = `coach_r2_overpremium`; }
                    else if (p < 0) { marginDelta -= 0.8; fillDelta += 2; coachKey = `coach_r2_underpremium`; }
                }

                // Discount policy.
                switch (d.discount) {
                    case `disciplined`: marginDelta += 0.8; healthDelta += 4; break;
                    case `deep`: marginDelta -= 1.4; healthDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r2_deepdisc`; break;
                    case `none`: healthDelta -= 4; coachKey = `coach_r2_nodisc`; break; // prices out sponsored learners who feed custom
                }

                // Variable-spend lever — the "slash to margin" trap.
                switch (d.variable) {
                    case `trim`: marginDelta += 0.8; break;
                    case `slash`: ds.qualityCut = true; marginDelta += 2.2; healthDelta -= 16; coachKey = `coach_r2_slash`; break;
                    case `hold`: healthDelta += 2; break;
                }

                summaryKey = (d.pricing === `segmented` && d.discount === `disciplined` && d.variable !== `slash`) ? `sum_r2_good` :
                             (d.pricing === `uniform` ? `sum_r2_uniform` :
                             (d.variable === `slash` ? `sum_r2_quality` :
                             (d.pricing === `discount` ? `sum_r2_discount` : `sum_r2_weak`)));
            } else if (round === 3) {
                // Mix, capacity ceiling, and the client renegotiation.
                switch (d.mix) {
                    case `balanced`: marginDelta += 1.6; fillDelta += 4; healthDelta += 4; coachKey = `coach_r3_balanced`; break;
                    case `custompush`: marginDelta += 0.6; fillDelta += 2; coachKey = `coach_r3_custompush`; break; // margin upside but capacity risk below
                    case `openonly`: marginDelta -= 1.2; fillDelta += 2; healthDelta -= 3; coachKey = `coach_r3_openonly`; break;
                }

                switch (d.faculty) {
                    case `develop`: healthDelta += 6; marginDelta += 0.4; break;
                    case `overbook`: ds.capacityBreached = true; healthDelta -= 12; marginDelta -= 0.5; coachKey = `coach_r3_overbook`; break;
                    case `untested`: ds.capacityBreached = true; healthDelta -= 14; coachKey = `coach_r3_untested`; break;
                }

                // Pushing custom hard without a bench triggers the capacity breach.
                if (d.mix === `custompush` && d.faculty !== `develop`) {
                    ds.capacityBreached = true;
                    healthDelta -= 5;
                    if (coachKey === `coach_r3_custompush`) coachKey = `coach_r3_capacity`;
                }

                switch (d.client) {
                    case `counter`: marginDelta += 1.4; healthDelta += 5; coachKey = `coach_r3_counter`; break;
                    case `concede`: ds.concededClient = true; marginDelta -= (this.MINING_CONTRIB / this.REVENUE) * 100; healthDelta -= 2; coachKey = `coach_r3_concede`; break;
                    case `walk`: marginDelta -= 1.0; fillDelta -= 2; healthDelta -= 4; coachKey = `coach_r3_walk`; break;
                }

                // Vetted-bench / QA investment protects quality as growth scales.
                ds.benchSpent = Math.round(ds.benchSpent + d.bench);
                if (d.bench >= 350) { healthDelta += 6; ds.capacityBreached = false; }
                else if (d.bench >= 150) { healthDelta += 3; }
                else if (d.bench <= 0 && d.mix === `custompush`) { healthDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r3_nobench`; }

                summaryKey = (d.mix === `balanced` && d.faculty === `develop` && d.client === `counter`) ? `sum_r3_good` :
                             (ds.capacityBreached ? `sum_r3_capacity` :
                             (d.client === `concede` ? `sum_r3_concede` : `sum_r3_weak`));
            } else if (round === 4) {
                // Approve the capacity investment — ROI, payback, break-even fill.
                // Incremental capacity revenue if the new rooms fill at a given rate.
                // New floor adds +33% capacity; potential incremental revenue at full
                // utilisation ≈ 33% of the open-enrollment revenue base it can serve.
                const incrRevAtFull = this.REVENUE * 0.55 * (this.CAP_UPLIFT / 100); // ≈ S/ 4.36M at 100% of new rooms
                const curMargin = ds.margin / 100;

                // Scenario sets the year-one fill assumption for the NEW rooms.
                let assumedFill;
                if (d.scenario === `optimistic`) assumedFill = 0.75;
                else if (d.scenario === `flat`) assumedFill = 0.40;
                else assumedFill = 0.50; // realistic ramp toward the existing 62%

                const incrContribOwn = incrRevAtFull * assumedFill * curMargin; // S/ M / yr
                // Break-even fill: contribution must cover the annual cost of the space.
                const annualCost = (d.invest === `own`) ? (this.CAPEX / 6) : (d.invest === `lease`) ? this.LEASE : 0; // capex annualised over ~6 yrs
                const contribPerFillPoint = (incrRevAtFull * curMargin) / 100; // S/ M per 1% fill
                ds.breakeven = contribPerFillPoint > 0 ? Math.round((annualCost / (incrRevAtFull * curMargin)) * 100) : 0;
                ds.roi = (d.invest === `nothing`) ? 0 : Math.round(((incrContribOwn - annualCost) / (d.invest === `own` ? this.CAPEX : this.LEASE)) * 100);
                ds.payback = (d.invest === `own` && incrContribOwn > 0) ? Math.round((this.CAPEX / incrContribOwn) * 10) / 10 :
                             (d.invest === `lease`) ? 0 : 0;
                ds.investChoice = d.invest;

                switch (d.invest) {
                    case `lease`: {
                        // Reversible capacity; fill the new rooms and margin/fill both rise.
                        fillDelta += 5;
                        marginDelta += 1.4;
                        healthDelta += 5;
                        coachKey = `coach_r4_lease`;
                        break;
                    }
                    case `own`: {
                        if (d.scenario === `optimistic`) {
                            ds.overInvested = true;
                            marginDelta -= 3.2;   // S/ 5.2M sunk while paying it down breaches the floor
                            fillDelta += 2;
                            healthDelta -= 6;
                            coachKey = `coach_r4_ownoptimistic`;
                        } else {
                            marginDelta -= 1.2;   // a defensible capex if scenario-tested, but cash-heavy
                            fillDelta += 4;
                            healthDelta += 2;
                            coachKey = `coach_r4_own`;
                        }
                        break;
                    }
                    case `nothing`: {
                        fillDelta -= 1;
                        marginDelta += 0.2;
                        healthDelta -= 3;
                        coachKey = `coach_r4_nothing`;
                        break;
                    }
                }

                switch (d.scenario) {
                    case `realistic`: healthDelta += 5; marginDelta += 0.4; break;
                    case `optimistic`: healthDelta -= 4; if (d.invest !== `own`) coachKey = `coach_r4_optimistic`; break;
                    case `flat`: healthDelta -= 2; break;
                }

                switch (d.breakeven) {
                    case `upfront`: healthDelta += 6; marginDelta += 0.4; if (d.invest === `lease`) coachKey = `coach_r4_breakeven`; break;
                    case `afterthought`: healthDelta -= 2; break;
                    case `skip`: healthDelta -= 6; coachKey = `coach_r4_noskip`; break;
                }

                // Overconfidence against a high break-even is its own error.
                if (d.confidence >= 80 && ds.breakeven >= ds.fill) { healthDelta -= 4; marginDelta -= 0.4; }
                else if (d.confidence <= 30 && d.invest === `own`) { healthDelta -= 2; }

                summaryKey = (d.invest === `lease` && d.scenario === `realistic` && d.breakeven === `upfront`) ? `sum_r4_good` :
                             (ds.overInvested ? `sum_r4_overinvest` :
                             (d.invest === `nothing` ? `sum_r4_nothing` : `sum_r4_weak`));
            }

            // ---- Apply margin, fill, health deltas (clamped). ----
            ds.margin = Math.max(0, Math.min(60, Math.round((ds.margin + marginDelta) * 10) / 10));
            ds.fill = Math.max(0, Math.min(100, Math.round(ds.fill + fillDelta)));
            ds.health = Math.max(0, Math.min(100, Math.round(ds.health + healthDelta)));

            // ---- Contribution is DERIVED. A low fill rate caps how much margin is
            // actually realised (perishable capacity); a quality collapse and a killed
            // flagship erode the revenue base the unit can sustain. ----
            let effectiveRevenue = this.REVENUE;
            if (ds.flagshipKilled) effectiveRevenue -= 1.3;      // lost custom leads from PAD alumni (~S/ 1.3M)
            if (ds.qualityCut) effectiveRevenue -= 0.8;          // sponsors flag declining quality
            if (ds.concededClient) effectiveRevenue -= 0.0;      // captured in margin already
            const fillFactor = 0.85 + 0.15 * (ds.fill / this.FRONTIER); // under-fill leaves contribution on the table
            ds.contribution = Math.round(effectiveRevenue * (ds.margin / 100) * Math.min(1.05, fillFactor) * 100) / 100;

            ds.marginHistory.push(ds.margin);
            ds.fillHistory.push(ds.fill);
            ds.contribHistory.push(ds.contribution);
            ds.healthHistory.push(ds.health);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                margin: ds.margin,
                marginDelta: Math.round(marginDelta * 10) / 10,
                fill: ds.fill,
                fillDelta: Math.round(fillDelta),
                contribution: ds.contribution,
                health: ds.health,
                meetsFloor: ds.margin >= this.FLOOR,
                roi: ds.roi,
                payback: ds.payback,
                breakeven: ds.breakeven,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _floorStatusLabel(margin) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (margin >= this.FLOOR) return t(`floor_ok`);
            if (margin >= this.FLOOR - 2) return t(`floor_near`);
            return t(`floor_under`);
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.fundprog-card-margin`);
                if (card) {
                    card.classList.toggle(`fundprog-margin-pass`, n >= self.FLOOR);
                    card.classList.toggle(`fundprog-margin-fail`, n < self.FLOOR);
                }
                return `${self._fmtNum(n, 1)}%`;
            });

            uiManager.bind(`fillDisplay`, `domainState.fill`, (v) => `${Math.round(Number(v))}%`);
            uiManager.bind(`contribDisplay`, `domainState.contribution`, (v) => `S/ ${self._fmtNum(Number(v), 2)}M`);
            uiManager.bind(`healthDisplay`, `domainState.health`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`floorDisplay`, `domainState.margin`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.fundprog-floor-bar`);
                if (bar) {
                    bar.classList.toggle(`fundprog-floor-ok`, n >= self.FLOOR);
                    bar.classList.toggle(`fundprog-floor-near`, n >= self.FLOOR - 2 && n < self.FLOOR);
                }
                return self._floorStatusLabel(n);
            });

            // Round 1 — analytical-rigor slider readout.
            const fo = document.getElementById(`focusInput`);
            const foReadout = document.getElementById(`focusReadout`);
            if (fo && foReadout) {
                foReadout.textContent = fo.value;
                fo.addEventListener(`input`, function() { foReadout.textContent = fo.value; });
            }

            // Round 2 — premium-price slider readout.
            const pm = document.getElementById(`premiumInput`);
            const pmReadout = document.getElementById(`premiumReadout`);
            if (pm && pmReadout) {
                pmReadout.textContent = pm.value;
                pm.addEventListener(`input`, function() { pmReadout.textContent = pm.value; });
            }
        }

        _fmtNum(v, dec) {
            // Locale-aware decimal: en "31.0", es "31,0".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(dec);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        getChartConfig() {
            return {
                fundChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Contribution margin (%)`,
                                data: [],
                                borderColor: `#2b4f80`,
                                backgroundColor: `rgba(43,79,128,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2b4f80`,
                                yAxisID: `y`
                            },
                            {
                                label: `Capacity fill rate (%)`,
                                data: [],
                                borderColor: `#2f8f7a`,
                                backgroundColor: `rgba(47,143,122,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f8f7a`,
                                yAxisID: `y`
                            },
                            {
                                label: `Strategic-health index`,
                                data: [],
                                borderColor: `#7d5fc0`,
                                backgroundColor: `rgba(125,95,192,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#7d5fc0`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#46505d`, boxWidth: 14 } },
                            title: { display: false },
                            annotation: undefined
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#79808b` }, grid: { color: `rgba(20,35,63,0.06)` },
                                title: { display: true, text: `0–100 (% / index)`, color: `#79808b` }
                            },
                            x: {
                                ticks: { color: `#79808b` }, grid: { color: `rgba(20,35,63,0.04)` },
                                title: { display: true, text: `Round`, color: `#79808b` }
                            }
                        }
                    }
                }
            };
