        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.marginHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                fundChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.marginHistory.map((v) => Math.round(v * 10) / 10) },
                        { data: ds.fillHistory.map((v) => Math.round(v)) },
                        { data: ds.healthHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim replica of the getPerformanceSummary composite (weighted sum minus
            // classic-error penalties). KPI scoring + weights + penalties unchanged.
            const margin = Math.round(ds.margin * 10) / 10;
            const fill = Math.round(ds.fill);
            const contribution = Math.round(ds.contribution * 100) / 100;
            const health = Math.round(ds.health);
            const marginScore = Math.min(100, (margin / this.FLOOR) * 100);
            const fillScore = Math.min(100, (fill / this.FRONTIER) * 100);
            const contribScore = Math.min(100, (contribution / (this.REVENUE * (this.FLOOR / 100))) * 100);
            let composite = Math.round(marginScore * 0.34 + fillScore * 0.20 + health * 0.26 + contribScore * 0.20);
            let penalty = 0;
            if (ds.flagshipKilled) penalty += 22;
            if (ds.qualityCut) penalty += 20;
            if (ds.concededClient) penalty += 10;
            if (ds.capacityBreached) penalty += 8;
            if (ds.overInvested) penalty += 14;
            return Math.max(0, composite - penalty);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-funding debrief scorecard (was: framework default that
            // discarded score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="fp-cm-target ' + (ok ? 'fp-cm-met' : 'fp-cm-missed') + '">'
                    + '<span class="fp-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.meetsFloor, t('tgt_floor'))
                + chip(!!summary.filledWell, t('tgt_fill'))
                + chip(!!summary.healthyBrand, t('tgt_health'))
                + chip(!!summary.cleanValue, t('tgt_clean'));
            const metric = function (label, val) {
                return '<div class="fp-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const nz = function (v) { return (v != null) ? v : '-'; };
            const metrics = ''
                + metric(t('kpi_margin'), nz(summary.margin) + '%')
                + metric(t('kpi_fill'), nz(summary.fill) + '%')
                + metric(t('kpi_contribution'), 'S/' + nz(summary.contribution) + 'M')
                + metric(t('kpi_health'), nz(summary.health));
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="fp-cm">'
                +   '<div class="fp-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="fp-cm-verdict">' + verdict + '</div>'
                +   '<div class="fp-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="fp-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="fp-cm-targets">' + targets + '</div>'
                +   '<div class="fp-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="fp-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const margin = Math.round(ds.margin * 10) / 10;
            const fill = Math.round(ds.fill);
            const contribution = Math.round(ds.contribution * 100) / 100;
            const health = Math.round(ds.health);

            const meetsFloor = margin >= this.FLOOR;
            const filledWell = fill >= this.FRONTIER - 4;     // ~71%+
            const healthyBrand = health >= 65;

            // The concept's headline value-destruction errors: killing the
            // demand-engine flagship on contribution alone, or buying margin by
            // gutting the experience that IS the product. These cannot earn a
            // funded win no matter how the recovered numbers look — that is the
            // whole lesson of the debrief. Conceding the client for nothing is a
            // real contribution loss but not value-destruction, so it costs the
            // composite rather than disqualifying the win.
            const valueDestroyed = ds.flagshipKilled || ds.qualityCut;

            // Composite: floor attainment, fill, strategic health, contribution
            // level — then debited for the classic errors so a destructive path
            // measurably underperforms a clean one even after health re-saturates.
            const marginScore = Math.min(100, (margin / this.FLOOR) * 100);
            const fillScore = Math.min(100, (fill / this.FRONTIER) * 100);
            const contribScore = Math.min(100, (contribution / (this.REVENUE * (this.FLOOR / 100))) * 100);
            let composite = Math.round(
                marginScore * 0.34 + fillScore * 0.20 + health * 0.26 + contribScore * 0.20
            );
            let penalty = 0;
            if (ds.flagshipKilled) penalty += 22;   // lost the alumni/custom demand engine
            if (ds.qualityCut) penalty += 20;        // NPS collapse, sponsors flagging quality
            if (ds.concededClient) penalty += 10;    // S/ 470K surrendered for a logo
            if (ds.capacityBreached) penalty += 8;   // grew past the faculty ceiling
            if (ds.overInvested) penalty += 14;      // capex sunk on an optimistic ramp
            composite = Math.max(0, composite - penalty);

            let pattern = `mixed`;
            if (valueDestroyed) pattern = `hollow`;  // margin bought by destroying value — beats every other label
            else if (meetsFloor && healthyBrand && filledWell) pattern = `funded`;
            else if (!meetsFloor) pattern = `shortfall`;
            else pattern = `mixed`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_missed`;
            if (valueDestroyed) perfKey = `grade_hollow`;
            else if (meetsFloor && healthyBrand && filledWell && composite >= 78) perfKey = `grade_funded`;
            else if (ds.overInvested) perfKey = `grade_overinvested`;
            else if (meetsFloor && healthyBrand) perfKey = `grade_floorheld`;
            else if (composite >= 58) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (pattern === `hollow`) insights.push(window.mySimulation.t(`insight_hollow`));
            else if (pattern === `funded`) insights.push(window.mySimulation.t(`insight_funded`));
            else if (pattern === `shortfall`) insights.push(window.mySimulation.t(`insight_shortfall`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.flagshipKilled) insights.push(window.mySimulation.t(`insight_flagship`));
            if (ds.uniformHike) insights.push(window.mySimulation.t(`insight_uniform`));
            if (ds.concededClient) insights.push(window.mySimulation.t(`insight_concede`));
            if (ds.overInvested) insights.push(window.mySimulation.t(`insight_overinvest`));
            if (ds.capacityBreached) insights.push(window.mySimulation.t(`insight_capacity`));
            if (ds.qualityCut) insights.push(window.mySimulation.t(`insight_quality`));
            if (meetsFloor && fill < this.FRONTIER - 8) insights.push(window.mySimulation.t(`insight_fillgap`));

            return {
                gradeKey: perfKey,
                score: composite,
                cleanValue: !valueDestroyed,
                margin: margin,
                fill: fill,
                contribution: contribution,
                health: health,
                meetsFloor: meetsFloor,
                filledWell: filledWell,
                healthyBrand: healthyBrand,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.flagshipKilled && ds.health < 55) return window.mySimulation.t(`hint_flagship`);
            if (ds.qualityCut) return window.mySimulation.t(`hint_quality`);
            if (ds.margin < this.FLOOR - 2 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_floor`);
            if (ds.uniformHike && ds.fill < this.START_FILL) return window.mySimulation.t(`hint_uniform`);
            if (ds.capacityBreached) return window.mySimulation.t(`hint_capacity`);
            if (ds.overInvested) return window.mySimulation.t(`hint_overinvest`);
            if (ds.margin >= this.FLOOR && ds.fill >= this.FRONTIER - 4 && ds.health >= 65) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.margin`, label: `Margin`, i18nKey: `col_margin`, formatter: (v) => `${self._fmtNum(Number(v), 1)}%` },
                { key: `results.fill`, label: `Fill`, i18nKey: `col_fill`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.contribution`, label: `Contribution`, i18nKey: `col_contrib`, formatter: (v) => `S/ ${self._fmtNum(Number(v), 2)}M` },
